import{z as i,x as B,o as r,c as p,q as t,j as s,D as l,d as e,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"RL 缩放律","description":"","frontmatter":{"title":"RL 缩放律","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rl-scaling-laws.md","filePath":"llm/rl-scaling-laws.md","lastUpdated":1791063341000}'),L={name:"llm/rl-scaling-laws.md"};function d(m,a,R,D,h,f){const o=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="rl-缩放律" tabindex="-1">RL 缩放律 <a class="header-anchor" href="#rl-缩放律" aria-label="Permalink to &quot;RL 缩放律&quot;">​</a></h1><div class="epigraph"><p>预训练有损失–算力曲线；RL 的曲线画的是优化强度对金标，并且经常先升后降。</p><footer>—— Gao 等奖励模型过优化的标度；OpenAI o1 / DeepSeek-R1 把更多 RL 算力换成推理时行为；Kimi k1.5 的报告</footer></div><p><a href="/llm/tool-integrated-rl">上一课</a>把环境变复杂。本单元最后一问：再堆 RL 算力是否总换来能力。缺口是：<strong>预训练缩放律不能直接抄到 RL——代理奖励会 Goodhart，墙钟还被生成长度吃掉。</strong> Gao、Schulman、Hilton 给了 RM 过优化随优化步与 RM 规模的经验律。o1、R1、k1.5 给出另一条：可验证 RL 算力 ↔ 推理表现。本课对照两条，接到下一单元「想多久」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kaplan / Hoffmann 律预测预训练损失。RL 没有平稳的交叉熵：目标是 \\(\\mathbb{E}[R]\\)，\\(R\\) 还在变（策略分布移、RM 过期）。能画的是：横轴 RL FLOPs 或步数，纵轴金标（AIME、隐藏测例、人类）。偏好 RM 上，Gao 曲线拐点随 RM 参数量推迟。可验证域拐点来自校验器洞与熵塌，形状不同，仍可能降。</p><p><span class="marginnote">术语翻译：缩放律就是「投入翻倍时收益怎么打折」的经验曲线。预训练版问「算力翻倍、损失降多少」；RL 版问「生成算力翻倍、金标涨多少，什么时候开始不涨甚至倒退」。</span></p><p>另一轴是推理时计算：同一套权，多想一会儿（预算、并行采样）也能涨分。训练 RL 与测试时计算可互换到何种程度，是 o1 类系统的核心产品问题，下一单元展开。本课只钉训练侧缩放。</p><h3 id="不要把代理-当损失" tabindex="-1">不要把代理 \\(r\\) 当损失 <a class="header-anchor" href="#不要把代理-当损失" aria-label="Permalink to &quot;不要把代理 $r$ 当损失&quot;">​</a></h3><p>预训练诚实画 val loss。RL 若画代理奖励，缩放律会永远上升。金标与墙钟必须进图。DAPO 用 AIME avg@32，并报步数相对 R1-Zero 配方减半，这才是可比较的缩放点。</p><p><span class="marginnote">组大小 \\(G\\)、长度、是否动态采样改变「一步」的 FLOPs。横轴要用 token 或焦耳，不要用未定义的 step。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验卡：基座规模、RL 提示数、生成 token 总数、是否 KL、奖励类型。画金标 vs 生成 token。扫：更多步 vs 更大 \\(G\\) vs 更长 \\(L\\)。经验：可验证域在熵未塌时单调一段时间；偏好域更早拐。RM 规模与策略规模的相对关系按 Gao：策略相对 RM 过强则更快过优化。</p>',12)),(r(),s(A,null,{default:l(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLOP%5B%22RL%20%E7%94%9F%E6%88%90%20FLOPs%22%5D%20--%3E%20GOLD%5B%22%E9%87%91%E6%A0%87%22%5D%0A%20%20FLOP%20--%3E%20PROXY%5B%22%E4%BB%A3%E7%90%86%20r%22%5D%0A%20%20PROXY%20--%3E%20UP%5B%22%E5%B8%B8%E5%8D%95%E8%B0%83%E5%8D%87%22%5D%0A%20%20GOLD%20--%3E%20HILL%5B%22%E5%85%88%E5%8D%87%E5%90%8E%E9%99%8D%E6%88%96%E9%A5%B1%E5%92%8C%22%5D%0A%20%20TT%5B%22%E6%B5%8B%E8%AF%95%E6%97%B6%E8%AE%A1%E7%AE%97%22%5D%20--%3E%20SWAP%5B%22%E4%B8%8E%E8%AE%AD%E7%BB%83%20RL%20%E9%83%A8%E5%88%86%E5%8F%AF%E4%BA%92%E6%8D%A2%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("与 "),E("a",{href:"/llm/kl-free-rl"},"无 KL"),e("：去掉 KL 让同一 FLOPs 走得更远，拐点可能更早，应用金标而不是「走得远」当成功。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：组 \\(G=16\\)、长度 \\(L=4096\\) 时，每条提示一步要生成 \\(16\\times 4096=65536\\) token；把 \\(G\\) 加到 64 而提示数不变，「一步」的生成 FLOPs 变四倍——拿 step 当横轴的两条曲线根本不可比。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"可验证 RL 的边际来自覆盖更多会分叉的题与更长搜索。边际递减：题库耗尽、熵塌、长度费用。偏好 RL 的边际被过优化截断。蒸馏（后课）把 RL 得到的长链行为用 SFT 交给小模型，是另一种缩放：一次 RL，多次学生。",-1)),(r(),s(A,null,{default:l(()=>[n(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%20RL%20%E7%94%9F%E6%88%90%20FLOPs%22%5D%20--%3E%20G%5B%22%E5%8A%A0%E7%BB%84%20G%EF%BC%9A%E5%90%8C%E9%A2%98%E5%A4%9A%E8%AF%95%E5%87%A0%E6%9D%A1%22%5D%0A%20%20BUD%20--%3E%20L%5B%22%E5%8A%A0%E9%95%BF%E5%BA%A6%20L%EF%BC%9A%E5%8D%95%E9%93%BE%E6%83%B3%E6%9B%B4%E4%B9%85%22%5D%0A%20%20BUD%20--%3E%20S%5B%22%E5%8A%A0%E6%AD%A5%E6%95%B0%EF%BC%9A%E8%BF%87%E6%9B%B4%E5%A4%9A%E9%A2%98%22%5D%0A%20%20G%20--%3E%20G1%5B%22%E9%A2%98%E5%85%A8%E5%AF%B9%20%2F%20%E5%85%A8%E9%94%99%E6%97%B6%E7%99%BD%E8%8A%B1%22%5D%0A%20%20L%20--%3E%20L1%5B%22%E9%95%BF%E5%BA%A6%E8%B4%B9%E7%94%A8%E6%B6%A8%EF%BC%9A%E7%86%B5%E5%A1%8C%E4%B8%8E%E8%83%A1%E8%A8%80%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E9%A2%98%E5%BA%93%E8%80%97%E5%B0%BD%EF%BC%9A%E8%BE%B9%E9%99%85%E9%80%92%E5%87%8F%22%5D%0A%20%20G1%20--%3E%20SAT%5B%22%E9%87%91%E6%A0%87%E9%A5%B1%E5%92%8C%20%E2%86%92%20%E6%97%A9%E5%81%9C%E6%88%96%E6%8D%A2%E8%BD%B4%22%5D%0A%20%20L1%20--%3E%20SAT%0A%20%20S1%20--%3E%20SAT%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">常见误区：初学者容易想拿 Chinchilla 式公式「算出」RL 的最优算力分配。RL 没有公开的对应公式：目标非平稳、奖励会 Goodhart、边际来源（题库、熵、长度）各自由不同机制封顶，只能逐点扫实验。</span></p><p><span class="marginnote">R1-Zero 从基座直接 RL，缩放的是「无 SFT 冷启动」的探索；R1 加冷启动，曲线不可与 Zero 混横轴。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有公开的类 Hoffmann 的 RL 最优分配公式。实践是：可验证轴堆 RL 直到金标饱和或费用墙；偏好轴早停。同一 FLOPs 花在更大 \\(G\\) 还是更长 \\(L\\)，边际不同，要分开发而不是合成一个「RL 步数」。下一单元从训练算力转到<strong>一次推理想多久</strong>，那是测试时缩放，与本课互补。</p><p>横轴用生成 token 或焦耳，不要用未定义的 step。同一算力花在 G 还是 L 上要分开画，拐点看金标不是代理 r。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RL 缩放必须画金标 vs 真实生成算力；代理 \\(r\\) 会假永远涨。</li><li>偏好域拐点见 Gao；可验证域受熵、题库、长度限制。</li><li>一步的 FLOPs 随 \\(G\\) 与 \\(L\\) 变，横轴要定义。</li><li>测试时计算是另一条轴，下一单元。</li><li>出处：Gao, Schulman, Hilton；OpenAI o1；DeepSeek-AI R1；Kimi k1.5；Kaplan/Hoffmann 仅作预训练对照。</li></ul>',7))])}const P=i(L,[["render",d]]);export{F as __pageData,P as default};
